// `cloudflare-env.d.ts` is generated by `pnpm cf-typegen` from wrangler.jsonc + .dev.vars.
// OAuth secrets are optional (unset providers are hidden), so they're declared here instead.
interface CloudflareEnv {
  GITHUB_CLIENT_ID?: string;
  GITHUB_CLIENT_SECRET?: string;
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  /** Local-only switch for Playwright; ignored unless APP_ENV is 'local'. */
  E2E_PASSWORD_AUTH?: string;
}
